3. /// <summary>
4. /// Entry point for the Logix Echo test harness.
5. /// </summary>
6. /// <remarks>
7. /// Exit codes are load-bearing - CI distinguishes "the logic is wrong" from
8. /// "the infrastructure did not come up":
9. /// <list type="bullet">
10. ///   <item><description>0 - every case passed</description></item>
11. ///   <item><description>1 - at least one case failed (a real logic failure)</description></item>
12. ///   <item><description>2 - the run never happened: bad arguments, missing ACD, chassis or download failure</description></item>
13. /// </list>
14. /// </remarks>
15. public static class Program
16. {
17.     private const int ExitPassed = 0;
18.     private const int ExitTestFailure = 1;
19.     private const int ExitInfrastructureFailure = 2;
20. 
21.     public static async Task<int> Main(string[] args)
22.     {
23.         try
24.         {
25.             return args.FirstOrDefault() switch
26.             {
