 namespace Acs.LogixEchoHarness;

 /// <summary>
 /// Entry point for the Logix Echo test harness.
 /// </summary>
 /// <remarks>
 /// Exit codes are load-bearing - CI distinguishes "the logic is wrong" from
 /// "the infrastructure did not come up":
 /// <list type="bullet">
 ///   <item><description>0 - every case passed</description></item>
 ///   <item><description>1 - at least one case failed (a real logic failure)</description></item>
 ///   <item><description>2 - the run never happened: bad arguments, missing ACD, chassis or download failure</description></item>
 /// </list>
 /// </remarks>
 public static class Program
 {
     private const int ExitPassed = 0;
     private const int ExitTestFailure = 1;
     private const int ExitInfrastructureFailure = 2;

     public static async Task<int> Main(string[] args)
     {
         try
         {
             return args.FirstOrDefault() switch
             {
                 "convert" => await ConvertAsync(args).ConfigureAwait(false),
                 "download" => await DownloadAsync(args).ConfigureAwait(false),
                 "echo-download" => await EchoDownloadAsync(args).ConfigureAwait(false),
                 "test" => await TestAsync(args[1..]).ConfigureAwait(false),
                 null or "--help" or "-h" => Usage(),
                 _ => await TestAsync(args).ConfigureAwait(false),
             };
         }
         catch (Exception ex)
         {
             Console.Error.WriteLine($"ERROR: {ex.Message}");
             Console.Error.WriteLine(ex);
             Console.Error.WriteLine("See docs/runbooks/troubleshooting.md");
             return ExitInfrastructureFailure;
         }
     }

     private static async Task<int> TestAsync(string[] args)
     {
         var options = Options.Parse(args);
         if (options is null)
         {
             return Usage();
         }

         var plan = TestPlan.Load(options.PlanPath);
         var acdPath = Path.GetFullPath(options.AcdPath ?? plan.Target.Artifact);

         if (!File.Exists(acdPath))
         {
             Console.Error.WriteLine($"ERROR: ACD not found: {acdPath}");
             Console.Error.WriteLine("Build it first: pwsh tools/logix/acd.ps1 -FromL5X <l5x> -ToAcd <acd>");
             return ExitInfrastructureFailure;
         }

         // The run id keeps concurrent workflow runs from colliding on one runner.
         var chassisName = string.IsNullOrWhiteSpace(options.RunId)
             ? plan.Target.Chassis
             : $"{plan.Target.Chassis}-{options.RunId}";

         var report = await new TestRunner(plan, acdPath).RunAsync(chassisName).ConfigureAwait(false);

         Console.WriteLine();
         Console.WriteLine(report.ToText());
         report.Write(options.ReportDirectory);

         return report.AllPassed ? ExitPassed : ExitTestFailure;
     }

     private static async Task<int> ConvertAsync(string[] args)
     {
         var source = Value(args, "--source");
         var destination = Value(args, "--destination");

         if (source is null || destination is null)
         {
             Console.Error.WriteLine("usage: LogixEchoHarness convert --source <file> --destination <file>");
             return ExitInfrastructureFailure;
         }

         await LogixSession.ConvertAsync(Path.GetFullPath(source), Path.GetFullPath(destination))
             .ConfigureAwait(false);
         return ExitPassed;
     }

     /// <summary>
     /// Download an ACD to a controller. Used by the CD workflow after the comm
     /// path has been resolved from <c>deploy/targets.yaml</c>.
     /// </summary>
     private static async Task<int> DownloadAsync(string[] args)
     {
         var acd = Value(args, "--acd");
         var commPath = Value(args, "--comm-path");

         if (acd is null || commPath is null)
         {
             Console.Error.WriteLine("usage: LogixEchoHarness download --acd <file.ACD> --comm-path <path>");
             return ExitInfrastructureFailure;
         }

         var fullPath = Path.GetFullPath(acd);
         Console.WriteLine($"downloading {fullPath}");
         Console.WriteLine($"        to {commPath}");

         await using var session = await LogixSession.OpenAsync(fullPath, commPath)
             .ConfigureAwait(false);
         await session.DownloadAndRunAsync().ConfigureAwait(false);

         Console.WriteLine($"controller is in {await session.ReadModeAsync().ConfigureAwait(false)}");
         return ExitPassed;
     }

     private static async Task<int> EchoDownloadAsync(string[] args)
     {
         var acd = Value(args, "--acd");
         if (acd is null)
         {
             Console.Error.WriteLine(
                 "usage: LogixEchoHarness echo-download --acd <file.ACD> [--run-id <id>]");
             return ExitInfrastructureFailure;
         }

         var fullPath = Path.GetFullPath(acd);
         if (!File.Exists(fullPath))
         {
             Console.Error.WriteLine($"ERROR: ACD not found: {fullPath}");
             return ExitInfrastructureFailure;
         }

         var runId = Value(args, "--run-id") ?? "echo-service-download";
         var chassisName = $"acs-ci-{runId}";
         await using var chassis = await EchoChassis.CreateAsync(chassisName, fullPath)
             .ConfigureAwait(false);
         Console.WriteLine($"downloading {fullPath} through Echo service");
         await chassis.DownloadProjectAsync(fullPath).ConfigureAwait(false);
         Console.WriteLine("Echo service download completed");
         return ExitPassed;
     }

     private static int Usage()
     {
         Console.WriteLine("""
             LogixEchoHarness - run YAML test plans against FactoryTalk Logix Echo.

               test     --plan <plan.tests.yaml> [--acd <file.ACD>] [--run-id <id>]
                        [--reports <dir>]
               convert  --source <file> --destination <file>
               download --acd <file.ACD> --comm-path <path>
               echo-download --acd <file.ACD> [--run-id <id>]

             Examples:
               dotnet run --project tests/harness/LogixEchoHarness -- \
                   --plan tests/cases/fl1-conveyor.tests.yaml --acd build/FL1_Main.ACD

             Exit codes: 0 passed, 1 test failure, 2 infrastructure failure.
             """);
         return ExitInfrastructureFailure;
     }

     private static string? Value(string[] args, string name)
     {
         var index = Array.IndexOf(args, name);
         return index >= 0 && index + 1 < args.Length ? args[index + 1] : null;
     }

     private sealed record Options(
         string PlanPath,
         string? AcdPath,
         string? RunId,
         string ReportDirectory)
     {
         public static Options? Parse(string[] args)
         {
             var plan = Value(args, "--plan");
             if (plan is null)
             {
                 return null;
             }

             return new Options(
                 PlanPath: Path.GetFullPath(plan),
                 AcdPath: Value(args, "--acd"),
                 RunId: Value(args, "--run-id"),
                 ReportDirectory: Value(args, "--reports") ?? Path.Combine("build", "reports"));
         }
     }
 }

