1. using System.Globalization;
2. using System.Net.NetworkInformation;
3. using RockwellAutomation.FactoryTalkLogixEcho.Api.Client;
4. using RockwellAutomation.FactoryTalkLogixEcho.Api.Interfaces;
5. 
6. namespace Acs.LogixEchoHarness;
7. 
8. /// <summary>
9. /// Owns the emulated chassis and controller for one test run.
10. /// </summary>
11. /// <remarks>
12. /// One of only two files in this repository that bind to a Rockwell SDK. Keeping
13. /// the surface small means an SDK version bump is a contained change.
14. ///
15. /// Teardown order matters: a chassis cannot be deleted while it still holds
16. /// controllers. <see cref="DisposeAsync"/> must run even when a test run throws,
17. /// or the next run collides with a leaked chassis.
18. /// </remarks>
19. public sealed class EchoChassis : IAsyncDisposable
20. {
21.     private readonly IServiceApiClientV2 _service;
22.     private readonly string _name;
23.     private ChassisData? _chassis;
24.     private ControllerData? _controller;
25. 
26.     private EchoChassis(IServiceApiClientV2 service, string name)
27.     {
28.         _service = service;
29.         _name = name;
30.     }
31. 
32.     /// <summary>Comm path for the LDSDK. The prefix routes through the virtual backplane.</summary>
33.     public string CommPath =>
34.         _controller is null
35.             ? throw new InvalidOperationException("controller has not been created")
36.             : @"EmulateEthernet\" + _controller.IPConfigurationData.Address;
37. 
38.     public string ControllerName => _controller?.ControllerName ?? "<none>";
39. 
40.     /// <summary>
41.     /// Download an ACD through the Echo service and wait for the operation to finish.
42.     /// </summary>
43.     /// <remarks>
44.     /// This uses Echo's supported service API rather than the Logix Designer SDK
45.     /// transport, so it isolates Echo project-download failures from FactoryTalk Linx.
46.     /// </remarks>
47.     public async Task DownloadProjectAsync(string acdPath)
48.     {
49.         if (_controller is null)
50.         {
51.             throw new InvalidOperationException("controller has not been created");
52.         }
53. 
54.         Trace($"sending ACD for Echo service download '{acdPath}'");
55.         using var fileHandle = await _service.SendFile(acdPath).ConfigureAwait(false);
56. 
57.         const int maxDownloadStartAttempts = 60;
58.         for (var attempt = 0; ; attempt++)
59.         {
60.             try
61.             {
62.                 Trace($"starting Echo service download attempt {attempt + 1}/{maxDownloadStartAttempts}");
63.                 await _service.Download(_controller.ControllerGuid, fileHandle).ConfigureAwait(false);
64.                 break;
65.             }
66.             catch (ServiceException ex) when (
67.                 attempt < maxDownloadStartAttempts - 1 &&
68.                 ex.Message.Contains(
69.                     "has not yet been synchronized with the requested IP address configuration",
70.                     StringComparison.OrdinalIgnoreCase))
71.             {
72.                 Trace(
73.                     $"controller IP synchronization is still pending on download attempt {attempt + 1}; " +
74.                     "retrying");
75.                 await Task.Delay(TimeSpan.FromSeconds(2)).ConfigureAwait(false);
76.             }
77.         }
78. 
79.         const int maxFeedbackAttempts = 120;
80.         for (var attempt = 0; attempt < maxFeedbackAttempts; attempt++)
81.         {
82.             var feedback = await _service.GetDownloadFeedback(_controller.ControllerGuid)
83.                 .ConfigureAwait(false);
84.             Trace(
85.                 $"Echo download state={feedback.State}, progress={feedback.Progress}% " +
86.                 $"({attempt + 1}/{maxFeedbackAttempts})");
87. 
88.             switch (feedback.State)
89.             {
90.                 case OperationState.Done:
91.                     return;
92.                 case OperationState.Failed:
93.                     throw new InvalidOperationException(
94.                         $"Echo service download failed: {string.Join("; ", feedback.Messages)}");
95.                 case OperationState.Canceled:
96.                     throw new InvalidOperationException("Echo service download was canceled");
97.             }
98. 
99.             await Task.Delay(TimeSpan.FromSeconds(2)).ConfigureAwait(false);
100.         }
101. 
102.         throw new TimeoutException("Echo service download did not finish within four minutes");
103.     }
104. 
105.     /// <summary>
106.     /// Stand up a chassis and a controller matching the supplied ACD.
107.     /// </summary>
108.     public static async Task<EchoChassis> CreateAsync(string chassisName, string acdPath)
109.     {
110.         if (!File.Exists(acdPath))
111.         {
112.             throw new FileNotFoundException($"ACD not found: {acdPath}", acdPath);
113.         }
114. 
115.         var service = ClientFactory.GetServiceApiClientV2("ACS Logix Harness");
116. 
117.         // The SDK formats messages and parses numbers per the current culture. Pin
118.         // it so a runner with a non-English locale does not change behaviour.
119.         service.Culture = new CultureInfo("en-US");
120. 
121.         var chassis = new EchoChassis(service, chassisName);
122.         try
123.         {
124.             Trace($"starting chassis sweep for '{chassisName}'");
125.             await chassis.SweepExistingAsync().ConfigureAwait(false);
126. 
127.             Trace($"creating chassis '{chassisName}'");
128.             chassis._chassis = await service
129.                 .CreateChassis(new ChassisUpdate
130.                 {
131.                     Name = chassisName,
132.                     Description = "Created by ACS Logix Echo harness"
133.                 })
134.                 .ConfigureAwait(false);
135.             Trace($"created chassis '{chassisName}' ({chassis._chassis.ChassisGuid})");
136. 
137.             Trace($"listing controllers for chassis '{chassisName}'");
138.             var existingControllers = await service
139.                 .ListControllers(chassis._chassis.ChassisGuid)
140.                 .ConfigureAwait(false);
141.             foreach (var existingController in existingControllers)
142.             {
143.                 Trace($"deleting stale controller '{existingController.ControllerName}' ({existingController.ControllerGuid})");
144.                 await service.DeleteController(existingController.ControllerGuid).ConfigureAwait(false);
145.             }
146. 
147.             // Echo reads the controller type, revision and slot out of the ACD
148.             // itself, so the emulated controller always matches the project.
149.             Trace($"sending ACD '{acdPath}'");
150.             var fileHandle = await service.SendFile(acdPath).ConfigureAwait(false);
151.             Trace($"reading controller info from ACD");
152.             var controllerUpdate = await service
153.                 .GetControllerInfoFromAcd(fileHandle)
154.                 .ConfigureAwait(false);
155.             controllerUpdate.ChassisGuid = chassis._chassis.ChassisGuid;
156.             controllerUpdate.Description = "Created by ACS Logix Echo harness";
157.             var controllerNetwork = SelectControllerNetwork(
158.                 await service.ListAvailableEthernetAddresses().ConfigureAwait(false));
159.             controllerUpdate.IPConfigurationData.Address = controllerNetwork.IPAddress;
160.             controllerUpdate.IPConfigurationData.Netmask = controllerNetwork.Netmask;
161.             Trace(
162.                 $"using Echo controller address '{controllerNetwork.IPAddress}' " +
163.                 $"with netmask '{controllerUpdate.IPConfigurationData.Netmask}'");
164. 
165.             const int maxSyncRetries = 60;
166.             for (var attempt = 0; ; attempt++)
167.             {
168.                 try
169.                 {
170.                     Trace($"creating controller attempt {attempt + 1} for '{chassisName}'");
171.                     chassis._controller = await service
172.                         .CreateController(controllerUpdate)
173.                         .ConfigureAwait(false);
174.                     Trace($"created controller '{chassis._controller.ControllerName}' ({chassis._controller.ControllerGuid}) at {chassis._controller.IPConfigurationData.Address}");
175.                     break;
176.                 }
177.                 catch (ServiceException ex) when (
178.                     attempt < maxSyncRetries &&
179.                     ex.Message.Contains(
180.                         "has not yet been synchronized with the requested IP address configuration",
181.                         StringComparison.OrdinalIgnoreCase))
182.                 {
183.                     Trace($"controller IP sync not ready on attempt {attempt + 1}; retrying after delay");
184.                     if (await chassis.TryAdoptExistingControllerAsync(controllerUpdate.Name)
185.                             .ConfigureAwait(false))
186.                     {
187.                         Trace($"adopted existing controller '{chassis._controller!.ControllerName}' ({chassis._controller.ControllerGuid})");
188.                         break;
189.                     }
190. 
191.                     await Task.Delay(TimeSpan.FromSeconds(2)).ConfigureAwait(false);
192.                 }
193.                 catch (ServiceException ex) when (
194.                     attempt < maxSyncRetries &&
195.                     ex.Message.Contains("Slot 0 is already occupied.", StringComparison.OrdinalIgnoreCase))
196.                 {
197.                     Trace($"slot 0 occupied on attempt {attempt + 1}; refreshing controller list");
198.                     if (await chassis.TryAdoptExistingControllerAsync(controllerUpdate.Name)
199.                             .ConfigureAwait(false))
200.                     {
201.                         Trace($"adopted existing controller '{chassis._controller!.ControllerName}' ({chassis._controller.ControllerGuid})");
202.                         break;
203.                     }
204. 
205.                     var controllers = await service
206.                         .ListControllers(chassis._chassis.ChassisGuid)
207.                         .ConfigureAwait(false);
208.                     if (!controllers.Any())
209.                     {
210.                         await Task.Delay(TimeSpan.FromSeconds(1)).ConfigureAwait(false);
211.                         continue;
212.                     }
213. 
214.                     foreach (var existingController in controllers)
215.                     {
216.                         await service.DeleteController(existingController.ControllerGuid)
217.                             .ConfigureAwait(false);
218.                     }
219. 
220.                     await Task.Delay(TimeSpan.FromSeconds(1)).ConfigureAwait(false);
221.                 }
222.             }
223. 
224.             Trace("refreshing controller data after creation");
225.             await chassis.RefreshControllerDataAsync().ConfigureAwait(false);
226.             return chassis;
227.         }
228.         catch
229.         {
230.             await chassis.DisposeAsync().ConfigureAwait(false);
231.             throw;
232.         }
233.     }
234. 
235.     /// <summary>
236.     /// Remove a chassis of the same name left behind by a crashed predecessor.
237.     /// </summary>
238.     private async Task SweepExistingAsync()
239.     {
240.         Trace($"listing chassis for sweep of '{_name}'");
241.         var existing = await _service.ListChassis().ConfigureAwait(false);
242.         foreach (var candidate in existing.Where(c =>
243.                      string.Equals(c.Name, _name, StringComparison.OrdinalIgnoreCase)))
244.         {
245.             Trace($"sweeping leaked chassis '{candidate.Name}' ({candidate.ChassisGuid})");
246.             await DeleteChassisAsync(candidate.ChassisGuid).ConfigureAwait(false);
247.         }
248.     }
249. 
250.     private async Task DeleteChassisAsync(Guid chassisGuid)
251.     {
252.         Trace($"listing controllers to delete for chassis {chassisGuid}");
253.         var controllers = await _service.ListControllers(chassisGuid).ConfigureAwait(false);
254.         foreach (var controller in controllers)
255.         {
