5. /// <summary>
6. /// Reads and writes controller tags through the Logix Designer SDK.
7. /// </summary>
8. /// <remarks>
9. /// The second and last file that binds to a Rockwell SDK. Everything the harness
10. /// needs is six operations: open, mode change, download, read tag, write tag,
11. /// close. Keeping it to six is what makes an SDK version bump reviewable.
12. ///
13. /// Only atomic types are addressable. Structures must be addressed member by
14. /// member, down to an atomic leaf - see docs/reference/ldsdk-api.md.
15. /// </remarks>
16. public sealed class LogixSession : IAsyncDisposable
17. {
18.     private static readonly string[] SupportedTypes =
19.         ["BOOL", "SINT", "INT", "DINT", "LINT", "REAL", "STRING"];
20. 
21.     private readonly LogixProject _project;
22.     private LogixSession(LogixProject project)
23.     {
24.         _project = project;
25.     }
26. 
27.     public static async Task<LogixSession> OpenAsync(string acdPath, string commPath)
28.     {
29.         Trace($"opening project '{acdPath}'");
30.         var project = await LogixProject.OpenLogixProjectAsync(acdPath).ConfigureAwait(false);
31.         Trace($"setting communications path '{commPath}'");
32.         await project.SetCommunicationsPathAsync(commPath).ConfigureAwait(false);
33.         Trace($"communications path set to '{commPath}'");
34.         return new LogixSession(project);
35.     }
36. 
37.     /// <summary>
38.     /// Put the controller in Program, download, and return it to Run.
39.     /// </summary>
40.     /// <remarks>
41.     /// A download into a controller that is not in Program mode is refused. This
42.     /// is also the reset between isolated cases: it is the only way to guarantee
43.     /// retentive tags and latched state start from the project's initial values.
44.     /// </remarks>
45.     public async Task DownloadAndRunAsync()
46.     {
47.         Trace("going online");
48.         await GoOnlineWithRetryAsync().ConfigureAwait(false);
49.         Trace("changing to Program mode");
50.         await ChangeModeWithRetryAsync(LogixProject.RequestedControllerMode.Program).ConfigureAwait(false);
51. 
52.         Trace("downloading project");
53.         await DownloadWithRetryAsync().ConfigureAwait(false);
54. 
55.         Trace("changing to Run mode");
56.         await ChangeModeWithRetryAsync(LogixProject.RequestedControllerMode.Run).ConfigureAwait(false);
57. 
58.         Trace("reading controller mode after download");
59.         var mode = await _project.ReadControllerModeAsync().ConfigureAwait(false);
60.         if (mode != LogixProject.ControllerMode.Run)
61.         {
62.             throw new InvalidOperationException(
63.                 $"controller is in {mode} after download, expected Run. " +
64.                 "A faulted controller usually means the project faulted on first scan.");
65.         }
66.     }
67. 
68.     public async Task<LogixProject.ControllerMode> ReadModeAsync() =>
69.         await _project.ReadControllerModeAsync().ConfigureAwait(false);
70. 
71.     public async Task WriteAsync(string xpath, string type, object? value)
72.     {
73.         Guard(type);
74.         var mode = LogixProject.OperationMode.Online;
75. 
76.         switch (type)
77.         {
78.             case "BOOL":
79.                 await _project.SetTagValueBOOLAsync(xpath, mode, ToBoolean(value)).ConfigureAwait(false);
80.                 break;
81.             case "SINT":
82.                 await _project.SetTagValueSINTAsync(xpath, mode, Convert.ToSByte(value)).ConfigureAwait(false);
83.                 break;
84.             case "INT":
85.                 await _project.SetTagValueINTAsync(xpath, mode, Convert.ToInt16(value)).ConfigureAwait(false);
86.                 break;
87.             case "DINT":
88.                 await _project.SetTagValueDINTAsync(xpath, mode, Convert.ToInt32(value)).ConfigureAwait(false);
89.                 break;
90.             case "LINT":
91.                 await _project.SetTagValueLINTAsync(xpath, mode, Convert.ToInt64(value)).ConfigureAwait(false);
92.                 break;
93.             case "REAL":
94.                 await _project.SetTagValueREALAsync(xpath, mode, Convert.ToSingle(value)).ConfigureAwait(false);
95.                 break;
96.             case "STRING":
97.                 await _project.SetTagValueSTRINGAsync(xpath, mode, value?.ToString() ?? string.Empty).ConfigureAwait(false);
98.                 break;
99.         }
100.     }
