 using RockwellAutomation.LogixDesigner;

 namespace Acs.LogixEchoHarness;

 /// <summary>
 /// Reads and writes controller tags through the Logix Designer SDK.
 /// </summary>
 /// <remarks>
 /// The second and last file that binds to a Rockwell SDK. Everything the harness
 /// needs is six operations: open, mode change, download, read tag, write tag,
 /// close. Keeping it to six is what makes an SDK version bump reviewable.
 ///
 /// Only atomic types are addressable. Structures must be addressed member by
 /// member, down to an atomic leaf - see docs/reference/ldsdk-api.md.
 /// </remarks>
 public sealed class LogixSession : IAsyncDisposable
 {
     private static readonly string[] SupportedTypes =
         ["BOOL", "SINT", "INT", "DINT", "LINT", "REAL", "STRING"];

     private readonly LogixProject _project;
     private LogixSession(LogixProject project)
     {
         _project = project;
     }

     public static async Task<LogixSession> OpenAsync(string acdPath, string commPath)
     {
         Trace($"opening project '{acdPath}'");
         var project = await LogixProject.OpenLogixProjectAsync(acdPath).ConfigureAwait(false);
         Trace($"setting communications path '{commPath}'");
         await project.SetCommunicationsPathAsync(commPath).ConfigureAwait(false);
         Trace($"communications path set to '{commPath}'");
         return new LogixSession(project);
     }

     /// <summary>
     /// Put the controller in Program, download, and return it to Run.
     /// </summary>
     /// <remarks>
     /// A download into a controller that is not in Program mode is refused. This
     /// is also the reset between isolated cases: it is the only way to guarantee
     /// retentive tags and latched state start from the project's initial values.
     /// </remarks>
     public async Task DownloadAndRunAsync()
     {
         Trace("going online");
         await GoOnlineWithRetryAsync().ConfigureAwait(false);
         Trace("changing to Program mode");
         await ChangeModeWithRetryAsync(LogixProject.RequestedControllerMode.Program).ConfigureAwait(false);

         Trace("downloading project");
         await DownloadWithRetryAsync().ConfigureAwait(false);

         Trace("changing to Run mode");
         await ChangeModeWithRetryAsync(LogixProject.RequestedControllerMode.Run).ConfigureAwait(false);

         Trace("reading controller mode after download");
         var mode = await _project.ReadControllerModeAsync().ConfigureAwait(false);
         if (mode != LogixProject.ControllerMode.Run)
         {
             throw new InvalidOperationException(
                 $"controller is in {mode} after download, expected Run. " +
                 "A faulted controller usually means the project faulted on first scan.");
         }
     }

     public async Task<LogixProject.ControllerMode> ReadModeAsync() =>
         await _project.ReadControllerModeAsync().ConfigureAwait(false);

     public async Task WriteAsync(string xpath, string type, object? value)
     {
         Guard(type);
         var mode = LogixProject.OperationMode.Online;

         switch (type)
         {
             case "BOOL":
                 await _project.SetTagValueBOOLAsync(xpath, mode, ToBoolean(value)).ConfigureAwait(false);
                 break;
             case "SINT":
                 await _project.SetTagValueSINTAsync(xpath, mode, Convert.ToSByte(value)).ConfigureAwait(false);
                 break;
             case "INT":
                 await _project.SetTagValueINTAsync(xpath, mode, Convert.ToInt16(value)).ConfigureAwait(false);
                 break;
             case "DINT":
                 await _project.SetTagValueDINTAsync(xpath, mode, Convert.ToInt32(value)).ConfigureAwait(false);
                 break;
             case "LINT":
                 await _project.SetTagValueLINTAsync(xpath, mode, Convert.ToInt64(value)).ConfigureAwait(false);
                 break;
             case "REAL":
                 await _project.SetTagValueREALAsync(xpath, mode, Convert.ToSingle(value)).ConfigureAwait(false);
                 break;
             case "STRING":
                 await _project.SetTagValueSTRINGAsync(xpath, mode, value?.ToString() ?? string.Empty).ConfigureAwait(false);
                 break;
         }
     }

     public async Task<object> ReadAsync(string xpath, string type)
     {
         Guard(type);
         var mode = LogixProject.OperationMode.Online;

         return type switch
         {
             "BOOL" => await _project.GetTagValueBOOLAsync(xpath, mode).ConfigureAwait(false),
             "SINT" => await _project.GetTagValueSINTAsync(xpath, mode).ConfigureAwait(false),
             "INT" => await _project.GetTagValueINTAsync(xpath, mode).ConfigureAwait(false),
             "DINT" => await _project.GetTagValueDINTAsync(xpath, mode).ConfigureAwait(false),
             "LINT" => await _project.GetTagValueLINTAsync(xpath, mode).ConfigureAwait(false),
             "REAL" => await _project.GetTagValueREALAsync(xpath, mode).ConfigureAwait(false),
             "STRING" => await _project.GetTagValueSTRINGAsync(xpath, mode).ConfigureAwait(false),
             _ => throw new NotSupportedException(type),
         };
     }

     /// <summary>
     /// Convert an L5X to an ACD, or the reverse, inferring direction from the
     /// destination extension. Used by <c>tools/logix/acd.ps1</c>.
     /// </summary>
     public static async Task ConvertAsync(string source, string destination)
     {
         var project = await LogixProject.OpenLogixProjectAsync(source).ConfigureAwait(false);
         await project.SaveAsAsync(destination, true, false).ConfigureAwait(false);
     }

     private static void Guard(string type)
     {
         if (!SupportedTypes.Contains(type))
         {
             throw new NotSupportedException(
                 $"'{type}' is not addressable by the Logix Designer SDK. " +
                 $"Supported: {string.Join(", ", SupportedTypes)}. " +
                 "Address atomic leaf members of a structure individually.");
         }
     }

     private static bool ToBoolean(object? value) => value switch
     {
         null => false,
         bool flag => flag,
         string text => bool.TryParse(text, out var parsed) ? parsed : text != "0",
         _ => Convert.ToInt64(value) != 0,
     };

     public ValueTask DisposeAsync()
     {
         _project.Dispose();
         return ValueTask.CompletedTask;
     }

     private async Task ChangeModeWithRetryAsync(LogixProject.RequestedControllerMode mode)
     {
         const int maxRetries = 5;
         for (var attempt = 0; ; attempt++)
         {
             try
             {
                 Trace($"change mode attempt {attempt + 1}/{maxRetries} -> {mode}");
                 await _project.ChangeControllerModeAsync(mode).ConfigureAwait(false);
                 return;
             }
             catch (OperationFailedException ex) when (
                 attempt < maxRetries &&
                 ex.Message.Contains("RxE_COMM_DTLERROR", StringComparison.OrdinalIgnoreCase))
             {
                 Trace($"change mode hit RxE_COMM_DTLERROR on attempt {attempt + 1}; retrying");
                 await Task.Delay(TimeSpan.FromSeconds(2)).ConfigureAwait(false);
                 await _project.GoOnlineAsync().ConfigureAwait(false);
             }
         }
     }

     private async Task GoOnlineWithRetryAsync()
     {
         const int maxRetries = 5;
         for (var attempt = 0; ; attempt++)
         {
             try
             {
                 Trace($"go online attempt {attempt + 1}/{maxRetries}");
                 await _project.GoOnlineAsync().ConfigureAwait(false);
                 return;
             }
             catch (OperationFailedException ex) when (
                 attempt < maxRetries &&
                 ex.Message.Contains("RxE_COMM_DTLERROR", StringComparison.OrdinalIgnoreCase))
             {
                 Trace($"go online hit RxE_COMM_DTLERROR on attempt {attempt + 1}; retrying");
                 await Task.Delay(TimeSpan.FromSeconds(2)).ConfigureAwait(false);
             }
         }
     }

     private async Task DownloadWithRetryAsync()
     {
         const int maxRetries = 5;
         for (var attempt = 0; ; attempt++)
         {
             try
             {
                 Trace($"download attempt {attempt + 1}/{maxRetries}");
                 await _project.DownloadAsync().ConfigureAwait(false);
                 return;
             }
             catch (OperationFailedException ex) when (
                 attempt < maxRetries &&
                 ex.Message.Contains("RxE_COMM_DTLERROR", StringComparison.OrdinalIgnoreCase))
             {
                 Trace($"download hit RxE_COMM_DTLERROR on attempt {attempt + 1}; retrying");
                 await Task.Delay(TimeSpan.FromSeconds(2)).ConfigureAwait(false);
                 await _project.GoOnlineAsync().ConfigureAwait(false);
             }
         }
     }

     private static void Trace(string message) =>
         Console.WriteLine($"{DateTimeOffset.UtcNow:O} [LogixSession] {message}");
 }

