 $RsLogix5000ClassIDSpanish = '{8E81A01F-5881-5BF2-8D57-EF3617B46612}'
 $RsLogix5000ClassIDChinese = '{A64729FB-F926-56C7-9121-A10C41087722}'
 $RsLogix5000ClassIDJapanese = '{926E17C2-F92E-50D7-8B83-C3CFD1DB7AD7}'
 $RsLogix5000ClassIDKorean = '{A88DFCE1-B976-5E3D-91E4-7DA363E86E4F}'
 $RsLogix5000ClassIDArray = @($RsLogix5000ClassID, 
