     Write-Host 'FactoryTalk Logix Echo System Configuration Utility'
     Write-Host 'Copyright (C) 2021 Rockwell Automation Technologies, Inc. All rights reserved.'
     Write-Host

     if ($Operations -eq @('All'))
     {
         $Operations = $SupportedOperations
     }

     if ($Operations -contains 'ConfigureDCOMPermissions')
     {
         $Operations = $Operations + 'FixLogixDesignerRegistry'
     }

     $Operations = $Operations | Sort | Get-Unique

     if (-Not (ValidateOperations $Operations))
     {
         Finish 101
     }

     if (-Not (CheckIfAdmin))
     {
         Write-Error "Error: This script needs to be run as Administrator." -Category PermissionDenied
