 function ValidateOperations($operations)
 {
     foreach ($operation in $operations)
     {
         if ($SupportedOperations -notcontains $operation)
         {
             Write-Error "Invalid value for Operations parameter: $operation" -Category InvalidArgument
             return $FALSE
         }
     }

     return $TRUE
 }


 function DescribeOperations($operations)
 {
     Write-Host "Following actions will be performed:"
     Write-Host

     foreach ($operation in $operations)
     {
         Write-Host "Operation $operation actions:"
         Write-Host
         Write-Host $OperationDescriptions[$operation]
         Write-Host
     }
 }


 function GetConfirmation()
 {
     if ($Confirm)
     {
         $title    = 'The script will now execute selected operations.'
         $question = 'Are you sure you want to proceed?'

         $choices = New-Object Collections.ObjectModel.Collection[Management.Automation.Host.ChoiceDescription]
         $choices.Add((New-Object Management.Automation.Host.ChoiceDescription '&Yes', 'Requested changes will be applied'))
         $choices.Add((New-Object Management.Automation.Host.ChoiceDescription '&No', 'No changes will be applied and the script will exit'))

         $decision = $Host.UI.PromptForChoice($title, $question, $choices, 1)
         if ($decision -eq 0)
         {
             return $true
         }
     }
     else
     {
         Write-Warning 'Running in unattended mode - applying changes without confirmation.'
         return $true
     }

     return $false
 }


 function Finish($exitCode)
 {
     if ($Confirm)
     {
         pause
     }

     exit $exitCode
 }


 function CheckIfAdmin()
 {
     $currentPrincipal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
     return $currentPrincipal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
 }


 function ExecuteOperations($operations)
 {
     Write-Host
     Write-Host "Executing operations..."

     foreach ($operation in $operations)
     {
         Write-Host "Executing operation $operation..."

         try
         {
             $result = &$operation
         }
         catch
         {
             $result = $false
         }

         if ($result -eq $true)
         {
             Write-Host "Operation $operation executed successfully."
         }
         else
         {
             Write-Host "Operation $operation failed."
         }
     }

     Write-Host "All operations executed."
 }


 function ConfigureDCOMPermissions()
 {
     New-PSDrive -PSProvider Registry -Root HKEY_LOCAL_MACHINE -Name HKLM -Scope Local -ErrorAction SilentlyContinue | Out-Null

     GrantLocalLaunchAndActivation $RsLogix5000AppID $ServiceUser
     GrantLocalLaunchAndActivation $RockwellDirectoryMultiplexerAppID $ServiceUser
     GrantLocalLaunchAndActivation $HarmonyAppID $ServiceUser
 }


 function GrantLocalLaunchAndActivation($appID, $user)
 {
     try
     {
         $appKey = Get-Item -Path "HKLM:$RegClassesRoot32\AppID\$appID" -ErrorAction Stop
     }
     catch
     {
         Write-Error "Cannot find registry key for application $appID. Probably Logix Designer is not installed. Please run the tool again after Logix Designer installation." -Category ObjectNotFound
         return $false
     }

     try
     {
         $ntAccount = New-Object System.Security.Principal.NTAccount($user) -ErrorAction Stop
         $SID = ($ntAccount.Translate([System.Security.Principal.SecurityIdentifier])).Value
     }
     catch
     {
         # This is never expected - we cannot continue
         Write-Error "Cannot get security identifier for user $user. Please contact support for more infromation." -Category ObjectNotFound
         return $false
     }

     try 
     {
         $appPermissions = ($appKey | Get-ItemProperty -Name "LaunchPermission" -ErrorAction Stop)."LaunchPermission"
         $securityDescriptor = New-Object System.Security.AccessControl.RawSecurityDescriptor($appPermissions, 0)
     } 
     catch 
     {
         Write-Host "Changing Launch and Activation policy to Custom for application $appID."

         $defaultKey = Get-Item -Path "HKLM:$RegSoftware32\Microsoft\Ole"
         $defaultPermissions = ($defaultKey | Get-ItemProperty -Name "DefaultLaunchPermission")."DefaultLaunchPermission"
         $securityDescriptor = New-Object System.Security.AccessControl.RawSecurityDescriptor($defaultPermissions, 0)
     }

     $NewAccessMask = $ComAccessMaskExecute + $ComAccessMaskExecuteLocal + $ComAccessMaskActivateLocal

     $acl = $securityDescriptor.DiscretionaryAcl
     $found = $false

     foreach ($entry in $acl) 
     {
         if ($entry.SecurityIdentifier -eq $SID -and $entry.AceType -eq [System.Security.AccessControl.AceQualifier]::AccessAllowed) 
         {
             Write-Host "Updating existing ACL entry for user $user application $appID."
             $entry.AccessMask = $entry.AccessMask -bor $NewAccessMask
             $found = $true
             break
         }
     }

     if (-not $found) {
         Write-Host "Creating new ACL entry for user $user for application $appID."
         $newEntry = New-Object System.Security.AccessControl.CommonAce(
             [System.Security.AccessControl.AceFlags]::None,
             [System.Security.AccessControl.AceQualifier]::AccessAllowed,
             $NewAccessMask,
             $SID,
             $false,
             $null)
         $acl.InsertAce($acl.Count, $newEntry)
     }

     $securityDescriptor.DiscretionaryAcl = $acl
     $binaryDescriptor = New-Object 'byte[]' $securityDescriptor.BinaryLength
     $securityDescriptor.GetBinaryForm($binaryDescriptor, 0)

     try
     {
         $appKey | New-ItemProperty -Name "LaunchPermission" -PropertyType Binary -Value $binaryDescriptor -Force -ErrorAction Stop | Out-Null
     }
     catch 
     {
         Write-Error "Failed to update COM permissions for application $appID"
         return $false
     }

     return $true
 }


 function FixProgramDataPermissions()
 {
     if (-Not (Test-Path $ProgramDataDirPath -PathType Container))
     {
         Write-Host "Directory $ProgramDataDirPath does not exist - skipping operation."
         return $true
     }

     Write-Host "Granting Full Control permissions for directory $ProgramDataDirPath to user $ServiceUser."

     # This will overwrite access rule if it already existed
     try
     {
         $acl = Get-Acl -Path $ProgramDataDirPath -ErrorAction Stop
     }
     catch
     {
         Write-Error "Failed to read ACL for directory $ProgramDataDirPath."
         return $false
     }

     $rule = New-Object System.Security.AccessControl.FileSystemAccessRule($ServiceUser, "FullControl", "ContainerInherit,ObjectInherit", "None", "Allow")
     $acl.SetAccessRule($rule)

     try
     {
         Set-Acl -Path $ProgramDataDirPath -AclObject $acl -ErrorAction Stop
     }
     catch
     {
         Write-Error "Failed to modify ACL for directory $ProgramDataDirPath."
         return $false
     }

     return $true
 }


 function FixLogixDesignerRegistry()
 {
     Write-Host "Fixing LogixDesigner registry keys."

     New-PSDrive -PSProvider Registry -Root HKEY_LOCAL_MACHINE -Name HKLM -Scope Local -ErrorAction SilentlyContinue | Out-Null
     foreach($classId in $RsLogix5000ClassIDArray)
     {
         $path = "${RegClassesRoot32}CLSID\$classId"

         try
         {
             # This will overwrite the value if it already existed
             Set-Itemproperty -path "HKLM:$path" -Name 'AppID' -Value $RsLogix5000AppID -ErrorAction Stop
         }
         catch
         {
             Write-Error "Cannot find registry key HKEY_LOCAL_MACHINE$path. Probably Logix Designer is not installed. Please run the tool again after Logix Designer installation." -Category ObjectNotFound
             return $false
         }
     }
     return $true
 }


