$vmIp = "192.168.112.131"

# Check what's installed on the VM
Invoke-Command -ComputerName $vmIp -ScriptBlock {
    Write-Host "=== .NET SDK Version ===" -ForegroundColor Cyan
    dotnet --version 2>$null || Write-Host "dotnet not in PATH"

    Write-Host "`n=== FactoryTalk Logix Echo ===" -ForegroundColor Cyan
    Get-Service -Name "*Echo*" -ErrorAction SilentlyContinue | Select-Object Name, Status, StartType

    Write-Host "`n=== Logix Echo Install Path ===" -ForegroundColor Cyan
    $echoPaths = @(
        "C:\Program Files\Rockwell Software\FactoryTalk Logix Echo",
        "C:\Program Files (x86)\Rockwell Software\FactoryTalk Logix Echo"
    )
    foreach ($path in $echoPaths) {
        if (Test-Path $path) {
            Write-Host "Found: $path"
            Get-ChildItem $path -Filter "*version*" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 3
        }
    }

    Write-Host "`n=== Repository Location ===" -ForegroundColor Cyan
    @(
        "C:\Git-Local\AB-Logix-CI-CD",
        "C:\Users\$env:USERNAME\Git-Local\AB-Logix-CI-CD",
        "C:\Users\$env:USERNAME\Desktop\AB-Logix-CI-CD"
    ) | ForEach-Object {
        if (Test-Path $_) { Write-Host "Found: $_" }
    }

    Write-Host "`n=== Network Adapters ===" -ForegroundColor Cyan
    Get-NetAdapter | Select-Object Name, Status, LinkSpeed | Format-Table -AutoSize
}

