toolCalls.args:
{"command":"
# Check if running as Administrator
$isAdmin = ([System.Security.Principal.WindowsIdentity]::GetCurrent().Groups -contains [System.Security.Principal.SecurityIdentifier]'S-1-5-32-544')
if (-not $isAdmin) {
    Write-Host "ERROR: Must run as Administrator" -ForegroundColor Red
    exit 1
}

Write-Host "=== Configuring Windows Defender for VM Performance ===" -ForegroundColor Cyan

# 1. Exclude the VM folder from real-time scanning
$vmPath = "C:\Users\MitchellLandreth\Virtual-Machines\VMWare\"
Write-Host "`n[Step 1] Adding VM folder to Windows Defender exclusions..." -ForegroundColor Green
Write-Host "Path: $vmPath"

try {
    Add-MpPreference -ExclusionPath $vmPath -ErrorAction Stop
    Write-Host "✓ Successfully added exclusion" -ForegroundColor Green
} catch {
    Write-Host "✗ Failed to add exclusion: $_" -ForegroundColor Red
}

# 2. Exclude .vmdk, .vmx, .vmss files from scanning
Write-Host "`n[Step 2] Excluding VMware file extensions..." -ForegroundColor Green
@("*.vmdk", "*.vmx", "*.vmss", "*.vmem") | ForEach-Object {
    try {
        Add-MpPreference -ExclusionExtension $_ -ErrorAction SilentlyContinue
        Write-Host "  ✓ Excluded: $_"
    } catch {
        Write-Host "  ✗ Failed: $_"
    }
}

# 3. Verify exclusions
Write-Host "`n[Step 3] Verifying exclusions..." -ForegroundColor Green
$prefs = Get-MpPreference
Write-Host "`nExclusion Paths:"
$prefs.ExclusionPath | ForEach-Object { Write-Host "  • $_" }
Write-Host "`nExcluded Extensions:"
$prefs.ExclusionExtension | ForEach-Object { Write-Host "  • $_" }

# 4. Check current scanning status
Write-Host "`n[Step 4] Current Defender Status..." -ForegroundColor Green
Get-MpComputerStatus | Select-Object RealTimeProtectionEnabled, IsTamperProtected, OnAccessProtectionEnabled

Write-Host "`n[SUMMARY]" -ForegroundColor Cyan
Write-Host @"
✓ VM folder excluded from real-time scanning
✓ VMware file extensions excluded
✓ Real-time protection still active for other files

This should significantly improve VM responsiveness without
compromising security on the rest of your system.

To disable Windows Update during heavy testing:
  Settings → Update & Security → Advanced Options → Pause updates
"@
","description":"Configure Windows Defender exclusions for VM performance on host"}

